package com.travbook.railtickets.adapter.out.persistence;
import com.travbook.railtickets.application.port.out.*;
import com.travbook.railtickets.domain.model.RailTicket.*;
import com.travbook.shared.domain.DomainFailure;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.ObjectMapper;
import java.time.Clock;
import java.util.*;
/** Provider simulator owns its durable effects. No platform transaction spans a provider call. */
public final class DurableMockRailReservations implements RailReservations {
 private final JdbcClient jdbc;private final TransactionTemplate tx;private final ObjectMapper json;private final Clock clock;private final RailTicketSelection selection;
 public DurableMockRailReservations(JdbcClient jdbc,TransactionTemplate tx,ObjectMapper json,Clock clock,RailTicketSelection selection){this.jdbc=jdbc;this.tx=tx;this.json=json;this.clock=clock;this.selection=selection;}
 public Optional<Current> current(UUID id){return tx.execute(t->jdbc.sql("select r.id,r.status,r.reference,(select count(*) from rail_provider_passenger where reservation_id=r.id and active) as units from rail_provider_reservation r where r.id=:id").param("id",id).query((r,n)->new Current(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getInt(4),"MOCK")).optional());}
 public Optional<Receipt> lookup(UUID operation){return jdbc.sql("select receipt::text from rail_provider_operation where operation_id=:id").param("id",operation).query(String.class).optional().map(s->json.readValue(s,Receipt.class));}
 private void lock(String key){jdbc.sql("select pg_advisory_xact_lock(hashtextextended(:key,0))").param("key",key).query((r,n)->true).single();}
 private Receipt receipt(UUID op,UUID id,String kind,String fingerprint,Receipt receipt){jdbc.sql("insert into rail_provider_operation(operation_id,reservation_id,operation,fingerprint,receipt) values(:op,:id,:kind,:fingerprint,cast(:receipt as jsonb))").param("op",op).param("id",id).param("kind",kind).param("fingerprint",fingerprint).param("receipt",json.writeValueAsString(receipt)).update();return receipt;}
 private Optional<Receipt> prior(UUID op,UUID id,String kind,String fingerprint){return jdbc.sql("select operation_id,fingerprint,receipt::text from rail_provider_operation where operation_id=:op or (reservation_id=:id and operation=:kind)").param("op",op).param("id",id).param("kind",kind).query((r,n)->{if(!r.getObject(1,UUID.class).equals(op)||!r.getString(2).equals(fingerprint))throw new DomainFailure(DomainFailure.Code.IDEMPOTENCY_CONFLICT,"Provider operation binding changed.");return json.readValue(r.getString(3),Receipt.class);}).optional();}
 public Receipt reserve(UUID op,UUID id,Quote q,boolean reject){String fingerprint=id+":"+q.id()+":"+reject;var existing=prior(op,id,"RESERVE",fingerprint);if(existing.isPresent())return existing.get();boolean valid=true;try{q.valid(clock.instant());selection.validate(q);}catch(DomainFailure e){if(Set.of(DomainFailure.Code.QUOTE_EXPIRED,DomainFailure.Code.OFFER_EXPIRED,DomainFailure.Code.SEARCH_EXPIRED,DomainFailure.Code.BOOKING_CONFLICT,DomainFailure.Code.OFFER_UNAVAILABLE).contains(e.code()))valid=false;else throw e;}final boolean termsValid=valid;var s=q.selection();var j=s.journey();var a=s.availability();String stock=j.supplier()+":"+j.number()+":"+j.origin().code()+":"+j.destination().code()+":"+j.departure()+":"+a.travelClass()+":"+a.quota();return tx.execute(t->{lock("rail-reservation:"+id);lock("rail-operation:"+op);var replay=prior(op,id,"RESERVE",fingerprint);if(replay.isPresent())return replay.get();lock("rail-stock:"+stock);int used=jdbc.sql("select coalesce(sum(quantity),0) from rail_provider_reservation where stock_key=:key and active").param("key",stock).query(Integer.class).single();int capacity=a.status()==com.travbook.rail.domain.model.Rail.Status.AVAILABLE?a.position():12;boolean ok=termsValid&&!reject&&!q.expired(clock.instant())&&used+s.passengers().size()<=capacity;Reservation status=ok?switch(a.status()){case AVAILABLE->Reservation.CONFIRMED;case RAC->Reservation.RAC;case WAITLIST->Reservation.WAITLIST;default->throw new IllegalStateException("Unbookable availability");}:Reservation.REJECTED;String ref="MOCK-PNR-"+id;jdbc.sql("insert into rail_provider_reservation(id,stock_key,status,reference,quantity,capacity,active) values(:id,:key,:status,:ref,:quantity,:capacity,:active)").param("id",id).param("key",stock).param("status",status.name()).param("ref",ref).param("quantity",s.passengers().size()).param("capacity",capacity).param("active",ok).update();if(ok)for(int index=0;index<s.passengers().size();index++)jdbc.sql("insert into rail_provider_passenger(reservation_id,passenger_index,active) values(:id,:index,true)").param("id",id).param("index",index).update();return receipt(op,id,"RESERVE",fingerprint,new Receipt(op,id,status,ok,ref,"MOCK"));});}
 public Receipt cancel(UUID op,UUID id){String fingerprint=id.toString();return tx.execute(t->{lock("rail-reservation:"+id);lock("rail-operation:"+op);var replay=prior(op,id,"CANCEL",fingerprint);if(replay.isPresent())return replay.get();var row=jdbc.sql("select stock_key,status,reference from rail_provider_reservation where id=:id for update").param("id",id).query((r,n)->List.of(r.getString(1),r.getString(2),r.getString(3))).optional().orElseThrow(()->new IllegalStateException("Unknown reservation"));lock("rail-stock:"+row.get(0));if(!Set.of("CONFIRMED","RAC","WAITLIST","CANCELLED").contains(row.get(1)))throw new IllegalStateException("Cannot cancel rejected reservation");jdbc.sql("update rail_provider_reservation set status='CANCELLED',active=false where id=:id").param("id",id).update();jdbc.sql("update rail_provider_passenger set active=false where reservation_id=:id").param("id",id).update();return receipt(op,id,"CANCEL",fingerprint,new Receipt(op,id,Reservation.CANCELLED,true,row.get(2),"MOCK"));});}

 public Optional<PassengerReceipt> lookupPassengers(UUID op){return jdbc.sql("select receipt::text from rail_provider_passenger_operation where operation_id=:op").param("op",op).query(String.class).optional().map(p->json.readValue(p,PassengerReceipt.class));}
 public PassengerReceipt cancelPassengers(UUID op,UUID id,List<Integer> indexes){var selected=indexes.stream().sorted().toList();return tx.execute(t->{lock("rail-reservation:"+id);lock("rail-operation:"+op);var prior=lookupPassengers(op);if(prior.isPresent()){var r=prior.get();if(!r.reservationId().equals(id)||!r.passengerIndexes().equals(selected))throw new DomainFailure(DomainFailure.Code.IDEMPOTENCY_CONFLICT,"Passenger cancellation operation changed.");return r;}var row=jdbc.sql("select stock_key,status,reference from rail_provider_reservation where id=:id for update").param("id",id).query((r,n)->List.of(r.getString(1),r.getString(2),r.getString(3))).single();lock("rail-stock:"+row.get(0));if(!Set.of("CONFIRMED","RAC","WAITLIST").contains(row.get(1)))throw new IllegalStateException("Reservation not active");if(selected.isEmpty()||new HashSet<>(selected).size()!=selected.size())throw new IllegalArgumentException("Invalid passenger selection");for(int index:selected)if(jdbc.sql("update rail_provider_passenger set active=false where reservation_id=:id and passenger_index=:index and active").param("id",id).param("index",index).update()!=1)throw new IllegalStateException("Passenger no longer active");int remaining=jdbc.sql("select count(*) from rail_provider_passenger where reservation_id=:id and active").param("id",id).query(Integer.class).single();jdbc.sql("update rail_provider_reservation set quantity=:quantity,active=:active,status=:status where id=:id").param("id",id).param("quantity",Math.max(1,remaining)).param("active",remaining>0).param("status",remaining==0?"CANCELLED":row.get(1)).update();var result=new PassengerReceipt(op,id,selected,remaining,row.get(2),"MOCK");jdbc.sql("insert into rail_provider_passenger_operation(operation_id,reservation_id,receipt) values(:op,:id,cast(:receipt as jsonb))").param("op",op).param("id",id).param("receipt",json.writeValueAsString(result)).update();return result;});}
}
